private void enlarge(final int size){
    int length = array.length;
    int minimumGrowth = length + size;
    int newLength = length;

    if (minimumGrowth < 0) { // overflow
        throw new RuntimeException("Maximum array size exceeded");
    }

    while (newLength < minimumGrowth) {
        newLength *= 2;
    }

    byte[] newArray = new byte[newLength];
    System.arraycopy(array, 0, newArray, 0, length);
    array = newArray;
}

public void enlarge(int size) {
	if (this.value.length < this.length + size) {
		int newLength = this.value.length * 2;
		if (newLength < this.length + size) {
			newLength = this.length + size;
		}
		byte[] newValue = new byte[newLength];
		System.arraycopy(this.value, 0, newValue, 0, this.value.length);
		this.value = newValue;
	}
}

