public void addToClassPath(Vector<URL> cpV, String dir) {

	File f = new File(dir);
	if (f.isDirectory()) {
		File[] files = f.listFiles();
		for (File file : files) {
			if (file.isFile() && file.getName().endsWith(".jar")) {
				try {
                    cpV.add(new URL("file://" + file.getPath()));
                } catch (MalformedURLException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) throws MalformedURLException {
    File[] jarFiles = new File(dir).listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File dir, String name) {
            return name.endsWith(".jar");
        }
    });
    for (File jarFile : jarFiles) {
        cpV.add(jarFile.toURI().toURL());
    }
}

