public String format(LoggingEvent event) {
    StringBuilder builder = new StringBuilder();
    String message = event.getMessage().toString();
    int i = 0;
    int j = 0;
    while (i < message.length()) {
        if (message.charAt(i) == '%') {
            j = i + 1;
            while (j < message.length() && Character.isLetterOrDigit(message.charAt(j))) {
                j++;
            }
            String specifier = message.substring(i + 1, j);
            if (specifier.equals("c")) {
                builder.append(event.getLoggerContext().getName());
            } else if (specifier.equals("C")) {
                builder.append(event.getLevel());
            } else if (specifier.equals("e")) {
                builder.append(event.getLocation().getClassName());
            } else if (specifier.equals("d")) {
                builder.append(event.getTimeStamp());
            } else if (specifier.equals("F")) {
                builder.append(event.getLocation().getFileName());
            } else if (specifier.equals("l")) {
                builder.append(event.getLocation().getLineNumber());
            } else if (specifier.equals("m")) {
                builder.append(event.getMessage().getFormattedMessage());
            } else if (specifier.equals("n")) {
                builder.append("\n");
            } else if (specifier.equals("p")) {
                builder.append(event.getLevel().getLocalizedLevelName());
            } else if (specifier.equals("t")) {
                builder.append(event.getThreadName());
            } else if (specifier.equals("x")) {
                builder.append(event.getNDC());
            } else {
                builder.append("??");
            }
            i = j;
        } else {
            builder.append(message.charAt(i));
            i++;
        }
    }
    return builder.toString();
}

