private static Type resolveTypeVariable(TypeVariable typeVar, Class<?> targetType) {
    Class targetClass = targetType;
    while (targetClass != null && targetClass != Object.class) {
        TypeVariable[] typeVars = targetClass.getTypeParameters();
        for (int i = 0; i < typeVars.length; i++) {
            if (typeVars[i].getName().equals(typeVar.getName())) {
                return typeVars[i].getBounds()[0];
            }
        }
        targetClass = targetClass.getSuperclass();
    }
    return null;
}

