public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the graph has at least one edge in the subgraph
    if (!vertices.isEmpty()) {
        // Get the first vertex in the subgraph
        V firstVertex = vertices.iterator().next();
        // Get the neighbors of the first vertex
        Set<V> neighbors = graph.getNeighbors(firstVertex);
        // Check if the neighbors are a subset of the vertices
        if (neighbors.containsAll(vertices)) {
            // If so, check if the subgraph is complete, i.e. a clique
            for (V vertex : vertices) {
                // Check if every vertex in the subgraph has an edge to every other vertex in the subgraph
                if (!graph.getNeighbors(vertex).containsAll(vertices)) {
                    return false;
                }
            }
            return true;
        }
    }
