public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    // load the trace
    Trace trace = Trace.fromFile(file);

    // get the thread snapshots
    List<ThreadSnapshot> snapshots = trace.getThreadSnapshots();

    // filter the snapshots based on the time ranges
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    for (ThreadSnapshot snapshot : snapshots) {
        long timestamp = snapshot.getTimestamp();
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                filteredSnapshots.add(snapshot);
                break;
            }
        }
    }

    return filteredSnapshots;
}

